#!/usr/bin/env bash
# Generates Đào Vàng source art with the Codex CLI. Usage: bash tools/dao-vang-art.sh [name ...]
# (no names = all). Writes art-src/dao-vang/<name>.png (git-ignored); tools/dao-vang-sprites.py processes them.
mkdir -p "$(dirname "$0")/../art-src/dao-vang"
cd "$(dirname "$0")/../art-src/dao-vang" || exit 1
HEAD='Use your image generation tool to generate ONE image, then save it as PNG to ./NAME.png in the current working directory (copy/convert the generated file there). Do not create or modify any other files.
STRICT: original design only — no Pokémon or any existing franchise character, and not the '"'"'Gold Miner'"'"' old man or its look.
STYLE: match the attached reference images — cheerful clean cartoon game art, bold dark-brown outlines, flat cel shading with one soft highlight, warm saturated colours.'

brief() {
  case "$1" in
    miner) echo 'BRIEF: a horizontal sprite sheet of THREE frames side by side, evenly spaced with wide gaps, on a flat pure magenta (#ff00ff) background, no shadows on the background, no ground, no text. Each frame shows the SAME character and prop at identical scale and position: a young Vietnamese girl miner wearing a conical nón lá hat, simple light-blue shirt, dark-brown trousers, ONE dark braid — SIMPLIFIED chibi proportions (big head, small body), few details, large clear shapes so she reads at 90 pixels tall. She stands on the LEFT side of a small sturdy wooden rope winch seen from the front (two round wooden side wheels, a drum wrapped with tan rope, a crank handle on the side facing her). The rope end hangs straight down from the centre bottom of the drum and is cut short (do not draw a claw). Frame 1: idle, one hand resting on the crank, smiling. Frame 2: cranking, handle up, determined grin, leaning in. Frame 3: cranking, handle down, effort face. Keep the winch identical in all three frames.' ;;
    claw) echo 'BRIEF: TWO separate objects side by side with a wide gap, on a flat pure magenta (#ff00ff) background, no text, no rope: a sturdy grey-steel three-prong grabbing claw, seen from the front, hub at the top with a small ring to tie a rope, prongs pointing DOWN. Left: claw OPEN (prongs spread wide). Right: the same claw CLOSED (prongs curled together). Chunky, simple, bold outline, readable when 60 pixels tall.' ;;
    treasures) echo 'BRIEF: a sprite sheet of EIGHT separate objects in a 4 columns x 2 rows grid, each object centred in its own cell with generous empty space between them, on a flat pure magenta (#ff00ff) background, no text, no shadows. Row 1: (1) a SMALL gold nugget — chunky and bright, simple shape with a big shine so it stays readable on a phone, (2) a MEDIUM gold nugget, (3) a LARGE heavy gold nugget boulder, (4) a sparkling light-blue cut diamond. Row 2: (5) a SMALL grey rock, (6) a LARGE grey boulder rock, (7) a tied burlap money sack with a big dark "?" printed on it, (8) a shiny round gold coin. Each object fills most of its cell.' ;;
    critters) echo 'BRIEF: a sprite sheet of EIGHT separate objects in a 4 columns x 2 rows grid, each centred in its own cell with generous empty space between them, on a flat pure magenta (#ff00ff) background, no text. Row 1: (1) a cute brown mole wearing aviator goggles on its forehead, walking to the RIGHT, side view, left foot forward, (2) the SAME mole walking right, right foot forward, (3) the same mole walking right carrying a sparkling light-blue diamond in its arms, (4) a red stick of dynamite with a short lit fuse. Row 2 (shop icons): (5) a round glass bottle of orange-red strength potion with a cork, (6) a green four-leaf lucky clover, (7) a small jar of diamond polish with a cloth and a sparkle, (8) a thick brown book with a grey rock drawn on its cover. Each object fills most of its cell.' ;;
    bg) echo 'BRIEF: a portrait 9:16 game background, no characters, no objects, no text, no UI. Top 16% of the height: bright blue sky with two soft white clouds. Just below: a thin strip of green grass with a few tufts along the horizon line. The remaining 84%: underground cross-section of layered earth in horizontal bands that get darker with depth — light warm brown, mid brown, reddish brown, dark chocolate brown at the bottom — with subtle wavy borders between bands, tiny scattered pebbles and a few thin roots just under the grass. Keep the earth calm and low-contrast so objects placed on top stay readable.' ;;
    shop) echo 'BRIEF: a portrait 9:16 game screen backdrop, no characters, no text: the inside of a cosy little wooden mining supply shop. Warm lantern light, plank walls, shelves with jars and tools along the TOP edge, a wide wooden counter along the BOTTOM edge. The large middle area is a calm, plain plank wall with nothing on it (UI cards will be drawn there). Warm, soft, low-contrast.' ;;
    poster) echo 'BRIEF: a portrait 3:4 key-art illustration for the game, no text, no logo, no UI. Top half: the young Vietnamese girl miner (nón lá conical hat, light-blue shirt, one braid, simplified chibi proportions) cranking her wooden rope winch on a grass edge under a blue sky, delighted. The rope runs down into a cross-section of layered brown earth where her steel claw grabs a huge shining gold nugget. Around it: a sparkling diamond, grey rocks, a "?" burlap sack, small gold nuggets, and a cute brown mole with aviator goggles peeking. Leave the bottom 25% as calm dark earth (a title will be placed there).' ;;
    banner) echo 'BRIEF: a wide 2:1 landscape key-art illustration, no text, no logo, no UI. Composition: everything interesting on the RIGHT 55%; the LEFT 45% is calm plain sky and plain dark earth (a title will be placed there). Right side: the young Vietnamese girl miner (nón lá conical hat, light-blue shirt, one braid, simplified chibi proportions) cranking a wooden rope winch on a grass edge; below, a cross-section of layered brown earth where her steel claw grabs a big shining gold nugget, with a diamond, a grey rock, a "?" sack and a cute brown mole with aviator goggles.' ;;
  esac
}

names=("$@")
[ ${#names[@]} -eq 0 ] && names=(miner claw treasures critters bg shop poster banner)
for n in "${names[@]}"; do
  printf '%s\n\n%s\n' "${HEAD//NAME/$n}" "$(brief "$n")" > "prompt-$n.txt"
  /opt/homebrew/bin/codex exec -C "$PWD" -s workspace-write --skip-git-repo-check \
    -i ../samples/dao-vang-miner.png -i ../samples/dao-vang-scene.png - < "prompt-$n.txt" > "log-$n.txt" 2>&1 &
done
wait
ls -la *.png
